            // Immediate stop and enter fault
            motorUp   := FALSE;
            motorDown := FALSE;
            errorFlag := TRUE;
            state     := 3;          // FAULT
        ELSIF openLimit THEN
            motorUp   := FALSE;
            motorDown := FALSE;
            errorFlag := FALSE;
            state     := 0;          // IDLE
        ELSE
            motorUp   := TRUE;
            motorDown := FALSE;
            errorFlag := FALSE;
        END_IF

    2: // CLOSING
        IF obstacle THEN
            // Reverse direction immediately
            motorUp   := TRUE;
            motorDown := FALSE;
            errorFlag := FALSE;
            state     := 1;          // OPENING
